# Hypothesis: templates = connected components with a 'rare' anchor color (count 1 in comp) attached to a shape.
# Stamp at every seed of the anchor color: translate comp so anchor->seed; write only bg cells.
def solve(I):
    H,W=len(I),len(I[0]); bg=collections.Counter(v for r in I for v in r).most_common(1)[0][0]
    # components (4-conn) of non-bg
    seen=set(); comps=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)]; comp=[]; seen.add((i,j))
                while st:
                    r,c=st.pop(); comp.append((r,c,I[r][c]))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<H and 0<=nc<W and (nr,nc) not in seen and I[nr][nc]!=bg:
                            seen.add((nr,nc)); st.append((nr,nc))
                comps.append(comp)
    out=[r[:] for r in I]
    templ=None
    # template comps: those with >=2 colors and exactly one anchor cell (color appearing once)
    for comp in comps:
        cnt=collections.Counter(v for _,_,v in comp)
        if len(cnt)>=2 and min(cnt.values())==1:
            anc=[p for p in comp if cnt[p[2]]==1][0]
            shape=[(r-anc[0],c-anc[1],v) for r,c,v in comp if (r,c)!=anc[0][:2] or True and (r,c)!=anc[0]]
            shape=[(r-anc[0],c-anc[1],v) for r,c,v in comp if (r,c)!=(anc[0][0],anc[0][1])]
            templ=(anc[0][0],anc[0][1],shape)
    # anchor color = templ anchor color
    ac=templ[2]
    for i in range(H):
        for j in range(W):
            if I[i][j]==ac:
                for dr,dc,v in templ[2]:
                    ni,nj=i+dr,j+dc
                    if 0<=ni<H and 0<=nj<W and I[ni][nj]==bg:
                        out[ni][nj]=v
    return out

