def comps(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    x,y=st.pop()
                    if (x,y) in seen or not(0<=x<H and 0<=y<W) or g[x][y]==bg: continue
                    seen.add((x,y)); comp.append((x,y,g[x][y]))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        st.append((x+dx,y+dy))
                out.append(comp)
    return out

