    bg=collections.Counter(v for r in I for v in r).most_common(1)[0][0]
    O=[row[:] for row in I]
    cs=comps(I,bg); seeds=[c[0][:2] for c in cs if len(c)==1]
    tmap={}
    for tc in [c for c in cs if len(c)>1]:
        mr=min(r for r,_,_ in tc); mcd=min(cc for _,cc,_ in tc)
        rel=[(r-mr,cc-mcd,v) for r,cc,v in tc]
        cnt=collections.Counter(v for _,_,v in rel)
        mk=[(r,cc,v) for r,cc,v in rel if cnt[v]==1][0]
        if len(mk)!=1: continue
        def transform(rel_r,rel_c):
            # identity or horizontal mirror about marker column
            if mir: return (rel_r,-rel_c)
            return (rel_r,rel_c)
        shape=[transform(rr,rc) for rr,rc,v in rel]
        # remove marker cell contribution; re-anchor markers relative to new origin
        mrr,mcr,_=mk[0]; mv=mk[1]
        shape=[(rr-mrr,rc-mcr,(mv if False else None),vv) for rr,rc,vv in shape if not (rr==mrr and rc==mcr)]
        # simpler: keep rel coords with marker removed and colors from original rel
        nshape=[(rr-mrr,rc-mcr,vv) for rr,rc,vv in shape if not (rr==mrr and rc==mcr)]
        tmap[mv]=[nshape]
    for sr,sc in seeds:
        v=I[sr][sc]
        if v in tmap:
            for dr,dc,w in tmap[v][0]:
                rr,cc=sr+dr, sc+dc
                if 0<=rr<len(O) and 0<=cc<len(O[0]) and O[rr][cc]==bg:
                    O[rr][cc]=w
    return O
